export function getBuiltinModels(providerId: string): OmniBuiltinModel[] {
  const alias = OMNI_PROVIDER_ID_TO_ALIAS[providerId] ?? providerId
  return OMNI_BUILTIN_MODELS[alias] ?? OMNI_BUILTIN_MODELS[providerId] ?? []
}
